SELECT (DATE_TRUNC('HOUR', "LOAD_HOUR")) AS "TIME_BUCKET", (CAST(CASE WHEN (SUM(ELAPSED_MS)) = 0 OR (SUM(ELAPSED_MS)) IS NULL THEN NULL ELSE CAST((SUM(QUEUED_PROVISIONING_MS)) AS DECIMAL(38, 15)) / CAST((SUM(ELAPSED_MS)) AS DECIMAL(38, 15)) END AS DECIMAL(38, 15))) AS "WH_QUEUE_PROVISIONING_PCT" FROM (SELECT "WAREHOUSE_NAME" AS WAREHOUSE_NAME, (DATE_TRUNC('HOUR', (TRY_CAST("START_TIME" AS TIMESTAMP)))) AS LOAD_HOUR, COUNT(*) AS QUERY_COUNT, SUM("QUEUED_OVERLOAD_TIME") AS QUEUED_OVERLOAD_MS, SUM("QUEUED_PROVISIONING_TIME") AS QUEUED_PROVISIONING_MS, SUM("TOTAL_ELAPSED_TIME") AS ELAPSED_MS, SUM("EXECUTION_TIME") AS EXECUTION_MS FROM query_history GROUP BY 1, 2) AS base GROUP BY (DATE_TRUNC('HOUR', "LOAD_HOUR")) ORDER BY "WH_QUEUE_PROVISIONING_PCT" DESC, "TIME_BUCKET" LIMIT 100
